#!/usr/bin/env bash
set -Eeuo pipefail
umask 077

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
ENV_FILE="$ROOT/.env.production"
LOCK_FILE="/run/lock/orbit-backup.lock"
TMP_DIR=""

fail() {
  echo "ORBIT backup failed: $*" >&2
  exit 1
}

[[ -r "$ENV_FILE" ]] || fail "missing protected $ENV_FILE"
for command_name in docker oci age gzip python3 flock sha256sum; do
  command -v "$command_name" >/dev/null 2>&1 || fail "required command not found: $command_name"
done

exec 9>"$LOCK_FILE"
flock -n 9 || fail "another backup is already running"

set -a
# The file is generated by free-stack.sh and kept mode 0600.
# shellcheck disable=SC1090
source "$ENV_FILE"
set +a

: "${ORBIT_BACKUP_BUCKET:?ORBIT_BACKUP_BUCKET is required}"
: "${ORBIT_BACKUP_NAMESPACE:?ORBIT_BACKUP_NAMESPACE is required}"
: "${ORBIT_BACKUP_AGE_RECIPIENT:?ORBIT_BACKUP_AGE_RECIPIENT is required}"

[[ "$ORBIT_BACKUP_BUCKET" =~ ^[A-Za-z0-9][A-Za-z0-9._-]{0,255}$ ]] || fail "invalid OCI bucket name"
[[ "$ORBIT_BACKUP_NAMESPACE" =~ ^[A-Za-z0-9_-]+$ ]] || fail "invalid OCI namespace"

MAX_BUCKET_BYTES="${ORBIT_BACKUP_MAX_BUCKET_BYTES:-16000000000}"
[[ "$MAX_BUCKET_BYTES" =~ ^[0-9]+$ ]] || fail "ORBIT_BACKUP_MAX_BUCKET_BYTES must be an integer"
(( MAX_BUCKET_BYTES > 0 && MAX_BUCKET_BYTES <= 16000000000 )) ||
  fail "backup cap must be between 1 byte and 16 GB; 16 GB is a hard ceiling"

[[ "$ORBIT_BACKUP_AGE_RECIPIENT" =~ ^age1[0-9a-z]{20,}$ ]] ||
  fail "ORBIT_BACKUP_AGE_RECIPIENT is not a valid age public recipient"

COMPOSE=(docker compose --env-file "$ENV_FILE" \
  -f "$ROOT/docker-compose.yml" \
  -f "$ROOT/deploy/production/compose.ingress.yaml")

TMP_DIR="$(mktemp -d /var/tmp/orbit-backup.XXXXXX)"
chmod 700 "$TMP_DIR"
cleanup() {
  if [[ -n "$TMP_DIR" && -d "$TMP_DIR" ]]; then
    rm -rf -- "$TMP_DIR"
  fi
}
trap cleanup EXIT

STAMP="$(date -u +%Y%m%dT%H%M%SZ)"
OBJECT_NAME="orbit/postgres-cluster-$STAMP.sql.gz.age"
ENCRYPTED_FILE="$TMP_DIR/postgres-cluster-$STAMP.sql.gz.age"
OBJECT_LIST="$TMP_DIR/object-list.json"

# Dump every database and global role (including the ORBIT and Keycloak
# databases) through the database container. Plaintext SQL never touches disk.
"${COMPOSE[@]}" exec -T postgres sh -eu -c '
  export PGPASSWORD="$POSTGRES_PASSWORD"
  exec pg_dumpall --clean --if-exists --host=127.0.0.1 --username="$POSTGRES_USER"
' | gzip -6 -c | age -r "$ORBIT_BACKUP_AGE_RECIPIENT" -o "$ENCRYPTED_FILE"

[[ -s "$ENCRYPTED_FILE" ]] || fail "encrypted dump is empty"
BACKUP_BYTES="$(stat -c '%s' "$ENCRYPTED_FILE")"

# The bucket must be dedicated to ORBIT backups. The cap deliberately stops
# below OCI's free 20 GB combined object-storage allowance and never deletes.
oci os object list \
  --bucket-name "$ORBIT_BACKUP_BUCKET" \
  --namespace "$ORBIT_BACKUP_NAMESPACE" \
  --all --fields name,size --auth instance_principal --output json > "$OBJECT_LIST"

CURRENT_BYTES="$(python3 - "$OBJECT_LIST" <<'PY'
import json
import sys
with open(sys.argv[1], encoding="utf-8") as source:
    payload = json.load(source)
items = payload.get("data")
if not isinstance(items, list):
    raise SystemExit("OCI object list response has no data array")
total = 0
for item in items:
    size = item.get("size")
    if not isinstance(size, int) or size < 0:
        raise SystemExit("OCI returned an invalid object size; refusing upload")
    total += size
print(total)
PY
)"

(( CURRENT_BYTES + BACKUP_BYTES <= MAX_BUCKET_BYTES )) ||
  fail "bucket cap reached: current=${CURRENT_BYTES} new=${BACKUP_BYTES} cap=${MAX_BUCKET_BYTES}; no object was uploaded"

SHA256="$(sha256sum "$ENCRYPTED_FILE" | awk '{print $1}')"
oci os object put \
  --bucket-name "$ORBIT_BACKUP_BUCKET" \
  --namespace "$ORBIT_BACKUP_NAMESPACE" \
  --name "$OBJECT_NAME" \
  --file "$ENCRYPTED_FILE" \
  --no-overwrite \
  --verify-checksum \
  --metadata "{\"sha256\":\"$SHA256\",\"format\":\"age-gzip-pg-dumpall\"}" \
  --auth instance_principal >/dev/null

# Verify that the named object exists and its remote size matches the local one.
oci os object head \
  --bucket-name "$ORBIT_BACKUP_BUCKET" \
  --namespace "$ORBIT_BACKUP_NAMESPACE" \
  --name "$OBJECT_NAME" \
  --auth instance_principal --output json > "$TMP_DIR/object-head.json"

REMOTE_BYTES="$(python3 - "$TMP_DIR/object-head.json" <<'PY'
import json
import sys
with open(sys.argv[1], encoding="utf-8") as source:
    payload = json.load(source)
headers = {str(k).lower(): v for k, v in payload.items()}
value = headers.get("content-length")
if value is None:
    raise SystemExit("OCI HEAD response has no content-length")
print(int(value))
PY
)"
[[ "$REMOTE_BYTES" == "$BACKUP_BYTES" ]] ||
  fail "uploaded object size mismatch (local=$BACKUP_BYTES remote=$REMOTE_BYTES)"

echo "Encrypted ORBIT PostgreSQL cluster backup uploaded."
echo "Object: $OBJECT_NAME"
echo "Bytes: $REMOTE_BYTES"
echo "SHA-256: $SHA256"
